INSERT OR REPLACE INTO episodes (id, conversation_id, step_index, role, content, summary, tags, timestamp) VALUES (1288, '0ec84150-17aa-4e1e-a048-c811d5c1a6b2', 101, 'assistant', 'Bẩm Ngài, Milestone M1 (State-of-the-Art Memory Architecture Research & Architectural Gap Analysis) đã hoàn thành xuất sắc 100%:

