INSERT OR REPLACE INTO episodes (id, conversation_id, step_index, role, content, summary, tags, timestamp) VALUES (1987, '468bb24d-1cd6-4520-9213-47986cdb5355', 124, 'assistant', 'Thưa Ngài, đây là thông tin thời tiết thời gian thực tại **quận Hoàng Mai, Hà Nội** hiện tại:

