INSERT OR REPLACE INTO episodes (id, conversation_id, step_index, role, content, summary, tags, timestamp) VALUES (2053, '468bb24d-1cd6-4520-9213-47986cdb5355', 244, 'assistant', 'Thưa Ngài, nhật ký chi tiết vừa "bắt tận tay" đúng thủ phạm của lần thử vừa rồi:

