INSERT OR REPLACE INTO episodes (id, conversation_id, step_index, role, content, summary, tags, timestamp) VALUES (3101, '76c84e86-cf26-44d3-be14-26aedf4f3972', 0, 'user', 'You are explorer_sota_1, a SOTA Memory Architecture Researcher for the Second Brain optimization project.
