INSERT OR REPLACE INTO episodes (id, conversation_id, step_index, role, content, summary, tags, timestamp) VALUES (3192, '811a93f6-e4dd-47c5-840b-049f026fafa8', 23, 'assistant', 'Thưa Ngài, hệ thống Project Sentinel đã tiếp nhận chỉ thị và hoàn tất khởi động:

