INSERT OR REPLACE INTO episodes (id, conversation_id, step_index, role, content, summary, tags, timestamp) VALUES (3201, '811a93f6-e4dd-47c5-840b-049f026fafa8', 41, 'assistant', 'Thưa Ngài, Sentinel xin gửi báo cáo tiến độ định kỳ:

- **Khởi động Phase 0 (Survey & Scope Mapping):** Project Orchestrator đã chia tách nhiệm vụ và triển khai 3 subagent Explorer chạy song song.
