INSERT OR REPLACE INTO episodes (id, conversation_id, step_index, role, content, summary, tags, timestamp) VALUES (3510, 'b33bbc89-3e71-4b6f-9951-f009d3d63f13', 0, 'user', 'You are worker_m3_1, the Core Engine Optimization Engineer for Milestone M3 of the Second Brain project.
