INSERT OR REPLACE INTO episodes (id, conversation_id, step_index, role, content, summary, tags, timestamp) VALUES (6676, '2c28037f-ef6b-478e-bc9c-195f57443206', 1569, 'assistant', 'Báo cáo Ngài, **hệ thống đã hoạt động chuẩn chỉ 100% không một tì vết!** (*Splendid, Sir!*)

