INSERT OR REPLACE INTO episodes (id, conversation_id, step_index, role, content, summary, tags, timestamp) VALUES (10038, 'd1368ad5-351c-483d-879d-f83add84f181', 5, 'assistant', 'Báo cáo Ngài, thông tin thời tiết khu vực **Hoàng Mai, Hà Nội** hôm nay:

