INSERT OR REPLACE INTO episodes (id, conversation_id, step_index, role, content, summary, tags, timestamp) VALUES (10044, '0cc985c7-fa5b-47b4-824a-e68ed6483259', 12, 'assistant', 'Thưa Ngài, lệnh **tắt màn hình** đã được kích hoạt thành công, đồng thời bản tin thời tiết cho ngày mai tại Hoàng Mai đã sẵn sàng phục vụ Ngài:

